interface LoanRepository {
    boolean hasActiveLoan(String customerId);
}

class LoanApprovalService { // warstwa biznesowa
    private final LoanRepository repository;
    LoanApprovalService(LoanRepository repository) { this.repository = repository; }

    boolean approve(String customerId, double amount, double monthlyIncome) {
        if (repository.hasActiveLoan(customerId)) return false;
        return amount <= monthlyIncome * 10; // regula biznesowa - zyje TYLKO tutaj
    }
}

class LoanController { // warstwa prezentacji
    private final LoanApprovalService service;
    LoanController(LoanApprovalService service) { this.service = service; }

    String handleLoanApplicationRequest(String customerId, double amount, double income) {
        boolean approved = service.approve(customerId, amount, income); // zna TYLKO Service
        return approved ? "Zatwierdzono" : "Odrzucono";
    }
}

class InMemoryLoanRepository implements LoanRepository {
    private final Set<String> activeLoans = new HashSet<>();
    public boolean hasActiveLoan(String customerId) { return activeLoans.contains(customerId); }
}

class LegacyFileBasedLoanRepository implements LoanRepository {
    // symulacja: w prawdziwym systemie odczyt z pliku/systemu zewnetrznego
    public boolean hasActiveLoan(String customerId) {
        System.out.println("Sprawdzam plik legacy dla: " + customerId);
        return false;
    }
}

